#pragma once

#include <algorithm>
#include <climits>
#include <string>

#include "../../utils/system.hpp"

namespace deep_ep::elastic {

// Role suites. On the role path an Attention rank runs {dispatch send, combine
// receive} and an FFN rank {dispatch receive, combine send}; a Masked rank sends
// and receives in every phase. Each suite picks its role's kernel and launch shape
// per phase. kShared and kSendBlock run v2.1's kernel generated from the shared
// launch arguments (same code, include hash, cache key and cubin; kSendBlock only
// launches fewer threads). kRoleKernel runs a separate kernel: the FFN dispatch is a
// generated copy of hybrid_dispatch.cuh (the edits in tests/role_kernels.py) and the
// Attention collect is new code (afdep_hybrid_collect.cuh). These shapes are invisible
// on the wire: no rank reads a peer's grid, and every protocol word is unchanged.
// kCountFirst is not: its count words carry an epoch and its sources write row flags.
enum class AfdLaunchShape {
    // v2.1's launch, identical on every role.
    kShared,
    // Directional hybrid Attention dispatch: the shared kernel without its forward warps.
    kSendBlock,
    // A role kernel of its own: the FFN dispatch receive (one NVLink domain and directional
    // hybrid) and the directional hybrid Attention combine.
    kRoleKernel,
    // Count-first dispatch of one NVLink domain (afdep_count_first.cuh): visible on the wire,
    // as the high half of each source's rank count word carries its epoch and the sources
    // write per-row flags into the FFN workspace.
    kCountFirst,
};

// AFDEP_SHARED_ROLE_KERNELS=1 launches every role kernel in v2.1's shared shape:
// one switch back to v2.1. Each shape also has its own control.
static bool afdep_role_suites() {
    return deep_ep::get_env<int>("AFDEP_SHARED_ROLE_KERNELS", 0) == 0;
}

// One NVLink domain keeps v2.1's launch shapes on both roles. Its receive-only kernels
// (FFN dispatch, Attention combine) launch the senders' grid, but CTAs 1.. exit about
// 0.6 us after launch (measured on H100), so only CTA 0 stays resident, and it owns
// its SM either way. A one-CTA receive therefore frees almost nothing, and it moved
// latency by about 0.3 us (1-2%) at 1-8 tokens, in both directions (docs/v2.1.md, R10).
//
// What the FFN receive does hold is the copy epilogue: a PDL dependent of 132
// max-shared-memory CTAs that launches once every receive CTA has triggered. The FFN
// sends nothing in dispatch, so its idle payload warps trigger right after entry and
// the epilogue occupies every SM, waiting, for the whole count and arrival wait. A
// Masked FFN also sends, so it triggers only near the end. The FFN receive therefore
// runs afdep_ffn_dispatch.cuh, a copy of dispatch.cuh generated by tests/role_kernels.py
// in which only the notify warps trigger: CTA 0 triggers once every source's counts
// have arrived, early enough to hide the epilogue's launch behind the payload, and the
// epilogue no longer holds the SMs from receive entry. Template, launch shape and every
// other statement are the shared kernel's (one-token 3A:1F pays ~0.4 us, where counts
// and payload arrive together; docs/v2.1.md section 15). AFDEP_SHARED_FFN_RECEIVE=1
// keeps the shared kernel; AFDEP_KEEP_ENTRY_BARRIERS, AFDEP_UNION_NOTIFY and
// AFDEP_ALL_RANK_EXIT imply it.
static bool afdep_ffn_receive_kernels() {
    return afdep_role_suites() and deep_ep::get_env<int>("AFDEP_SHARED_FFN_RECEIVE", 0) == 0;
}

// Count-first dispatch (one NVLink domain). Payload-first, the FFN copy epilogue starts only
// after every source's payload has arrived. Count-first issues each source's counts before
// its payload (a source-local gate) and tags the rank count word with the source's epoch; the
// source lane that stored a row then releases that row's flag, set to the epoch, in the FFN
// workspace. The FFN receive records the epochs, triggers the copy epilogue after the count
// wait and releases a prefix-ready word P after the prefix sums. The epilogue waits on P
// instead of dispatch completion, and its CTAs claim units of rows that each wait for their
// own flag, so the copy streams behind the ingress. Flags are never cleared: epochs strictly
// grow, so only this exchange's write of a row matches.
// The decision is uniform per exchange: the Buffer latches the minimum bucket at construction
// (afdep/deepep.py checks it agrees on every rank) and every rank passes the same bucket.
// Below it every kernel, cubin and wire word is the payload-first one, so small buckets pay
// nothing. AFDEP_COUNT_FIRST_MIN_BUCKET sets it (0, the default here, is off until the screen
// picks one). AFDEP_PAYLOAD_FIRST=1 keeps the payload-first kernels; so do
// AFDEP_SHARED_ROLE_KERNELS, AFDEP_SHARED_FFN_RECEIVE and every control that implies it.
constexpr int kAfdepCountFirstDefaultMinBucket = 0;
static int afdep_count_first_min_bucket() {
    return afdep_ffn_receive_kernels() and deep_ep::get_env<int>("AFDEP_PAYLOAD_FIRST", 0) == 0 ?
        std::max(0, deep_ep::get_env<int>("AFDEP_COUNT_FIRST_MIN_BUCKET", kAfdepCountFirstDefaultMinBucket)) : 0;
}

// Flag geometry, mirrored from afdep_count_first.cuh (pinned by a unit test): flags start at
// int64 word kAfdepCountFirstFlagBase of the directed-exit region, one per source slot.
constexpr int kAfdepCountFirstMaxSources = 32;
constexpr int kAfdepCountFirstMaxFfnRanks = 64;
constexpr int kAfdepCountFirstFlagBase = 4238;
constexpr int kAfdepCountFirstFlagStride = 1;
constexpr int64_t kAfdepCountFirstRegionWords = 1 << 20;
// The copy epilogue keeps its double-buffered unit claim after the TMA buffers.
constexpr int kAfdepCountFirstClaimBytes = 128;
static bool afdep_count_first_flags_fit(const int num_sources, const int bucket) {
    return kAfdepCountFirstFlagBase + static_cast<int64_t>(num_sources) * bucket * kAfdepCountFirstFlagStride <=
        kAfdepCountFirstRegionWords;
}

// Screen arm, latched with the minimum bucket: "source" runs count-first sources against the
// payload-first FFN receive (the count low halves decode unchanged and the flags go unread),
// isolating the sender's cost. The Buffer latches the raw value unchecked, because a throw in
// one rank's constructor would leave its peers in the collective window registration;
// afdep/deepep.py rejects any other value on every rank after its agreement gather, and every
// dispatch asserts it while the minimum bucket is on.
static std::string afdep_count_first_arm() {
    return deep_ep::get_env<std::string>("AFDEP_COUNT_FIRST_ARM", "full");
}

static bool afdep_count_first_arm_valid(const std::string& arm) {
    return arm == "full" or arm == "source";
}

// Screen knobs, read per exchange. None reaches the wire: the gate and counting loop are
// source-local, the unit size and epilogue grid FFN-local.
// Tokens a source stores before the gate (AFDEP_COUNT_FIRST_UNGATE=1: every token).
static int afdep_count_first_ungated_tokens() {
    if (deep_ep::get_env<int>("AFDEP_COUNT_FIRST_UNGATE", 0) != 0)
        return INT_MAX;
    return std::max(0, deep_ep::get_env<int>("AFDEP_COUNT_FIRST_UNGATED_TOKENS", 0));
}

// AFDEP_COUNT_FIRST_WARP_COUNT=1 keeps one token per notify warp in the source's counting loop.
static bool afdep_count_first_thread_count() {
    return deep_ep::get_env<int>("AFDEP_COUNT_FIRST_WARP_COUNT", 0) == 0;
}

// Fewest rows per claimed epilogue unit (1 spreads rows over every SM).
static int afdep_count_first_unit_min_rows() {
    return std::max(1, deep_ep::get_env<int>("AFDEP_COUNT_FIRST_UNIT_MIN_ROWS", 1));
}

// Copy epilogue CTAs (0: every SM).
static int afdep_count_first_epilogue_sms() {
    return std::max(0, deep_ep::get_env<int>("AFDEP_COUNT_FIRST_EPILOGUE_SMS", 0));
}

// Directional hybrid (every NVLink domain holds one role). The shared kernels launch
// notify, scale-out and forward warps on both roles, and in combine scale-up and
// forward warps; 192 channels (24 SMs x 8) pair channel c's sender with channel c's
// receiver. Each role launches only the classes it uses, with every channel, QP,
// shared-memory slot, tail and signal unchanged. The classes dropped below took part
// only in block and grid synchronisation that counts launched threads (__syncthreads,
// grid sync); every thread_idx-indexed statement on these paths is in the notify warps.
// - Attention dispatch: notify and scale-out warps; its forward warps (the trailing
//   class) only joined the exit grid sync (and the entry grid sync under
//   AFDEP_ATTENTION_GRID_SYNC=1). The shared cubin is launched with fewer threads.
//   AFDEP_SHARED_HYBRID_SEND=1 keeps the shared block.
static bool afdep_hybrid_send_blocks() {
    return afdep_role_suites() and deep_ep::get_env<int>("AFDEP_SHARED_HYBRID_SEND", 0) == 0;
}

// Sparse directional hybrid (afdep_sparse_hybrid.cuh, opt-in, measured on the 12-domain screen).
// Every rank must set both switches alike: the FFN recomputes each source's channels.
// - AFDEP_HYBRID_STAGGER=1: the Attention dispatch runs afdep_source_hybrid_dispatch.cuh, a copy
//   of hybrid_dispatch.cuh generated by tests/role_kernels.py in which a source s of S with at most
//   AFDEP_HYBRID_STAGGER_MAX_TOKENS tokens (default: any) puts token i on channel (i + s*C/S) mod C,
//   so at small batches the sources' first tokens ride different channels instead of all queueing
//   on FFN forward warp 0. Same send-block shape. On the 12-domain screen staggering every batch
//   wins at every size with sparse combine (64 tokens -26.6% vs -13.7% unstaggered), but costs
//   +0.7..+2.2% at 64 and 128 tokens without it, where a bound of C/4 avoids that.
// - AFDEP_HYBRID_SPARSE_DISPATCH=1: each source also publishes its token count to every FFN domain
//   and sends finish tails only on channels that carried a token; the FFN dispatch runs
//   afdep_ffn_sparse_hybrid_dispatch.cuh, whose forwarders retire the other lanes from the count.
//   At T tokens an FFN GPU's NIC takes S*min(T, C) finish atomics plus S count words instead of S*C.
//   afdep/deepep.py rejects ranks that resolve these switches differently (including through the
//   role-local AFDEP_SHARED_* shape controls they need), instead of letting the protocol hang.
// - AFDEP_HYBRID_SPARSE_COMBINE=1: each source channel also records the FFN domains it put a token
//   for; the FFN combine runs afdep_ffn_sparse_hybrid_combine.cuh and signals a source on a channel
//   only if it replied to that source there, plus channel 0 to every source (a done witness: every
//   signal follows the FFN dispatch kernel, so a source that sent nothing cannot start its next
//   exchange early), and the Attention collect, afdep_sparse_hybrid_collect.cuh, waits for exactly
//   those. An FFN GPU's NIC then issues about S*min(T, C) combine signals instead of S*C.
// - FFN dispatch: notify and forward warps; its scale-out warps (between them) only
//   joined the entry NVLink barrier's __syncthreads and grid sync and the exit grid
//   sync. Forward warp f keeps channel sm*C+f, its QP and TMA slot
//   C+f and the shared launch bound, in afdep_ffn_hybrid_dispatch.cuh, a copy of
//   hybrid_dispatch.cuh generated by tests/role_kernels.py (pinned by a unit test).
//   AFDEP_SHARED_HYBRID_FORWARD=1 keeps the shared kernel.
static bool afdep_hybrid_forward_kernels() {
    return afdep_role_suites() and deep_ep::get_env<int>("AFDEP_SHARED_HYBRID_FORWARD", 0) == 0;
}

// Sparse directional hybrid switches (described above).
static bool afdep_hybrid_stagger() {
    return afdep_hybrid_send_blocks() and deep_ep::get_env<int>("AFDEP_HYBRID_STAGGER", 0) != 0;
}

// The largest batch a source staggers (0: never; default: any).
static int afdep_hybrid_stagger_max_tokens() {
    if (not afdep_hybrid_stagger())
        return 0;
    const auto max_tokens = deep_ep::get_env<int>("AFDEP_HYBRID_STAGGER_MAX_TOKENS", -1);
    return max_tokens < 0 ? INT_MAX : max_tokens;
}

static bool afdep_hybrid_sparse_dispatch() {
    return afdep_hybrid_send_blocks() and afdep_hybrid_forward_kernels() and
        deep_ep::get_env<int>("AFDEP_HYBRID_SPARSE_DISPATCH", 0) != 0;
}

static bool afdep_hybrid_sparse_combine() {
    return afdep_hybrid_send_blocks() and afdep_role_suites() and
        deep_ep::get_env<int>("AFDEP_SHARED_HYBRID_COLLECT", 0) == 0 and
        deep_ep::get_env<int>("AFDEP_HYBRID_SPARSE_COMBINE", 0) != 0;
}

// - Attention combine: a receive-only phase. Its scale-up warps return at once and
//   its forward warps only clear their channel's scale-up tails and wait for, then
//   clear, each FFN domain's finish signal, holding 24 SMs for the whole combine.
//   afdep_hybrid_collect.cuh runs those statements for every channel in one CTA, at
//   the same shared memory (it still owns its SM), without the shared kernel's two
//   local entry grid syncs (see that file); the reduce epilogue still waits for its
//   completion. AFDEP_SHARED_HYBRID_COLLECT=1 keeps the shared kernel.
static bool afdep_hybrid_collect_kernels() {
    return afdep_role_suites() and deep_ep::get_env<int>("AFDEP_SHARED_HYBRID_COLLECT", 0) == 0;
}

}  // namespace deep_ep::elastic
